package com.yourorg.keycloak;

import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.MultivaluedMap;
import jakarta.ws.rs.core.Response;
import org.jboss.logging.Logger;
import org.keycloak.authentication.AuthenticationFlowError;
import org.keycloak.authentication.ClientAuthenticationFlowContext;
import org.keycloak.authentication.authenticators.client.AbstractClientAuthenticator;
import org.keycloak.models.ClientModel;
import org.keycloak.OAuth2Constants;
import org.keycloak.provider.ProviderConfigProperty;

import java.util.Collections;
import java.util.List;
import java.util.Map;


/**
 * X509 Header Client Authenticator — core SPI implementation.
 *
 * This class is instantiated per-request by the Factory.
 *
 * Responsibility:
 *   1. Extract client_id from the POST body
 *   2. Look up the client in Keycloak
 *   3. Read the cert PEM from the x-mtls-cert header
 *   4. Read the stored cert PEM from the client's attributes
 *   5. Compare both certs by SHA-256 fingerprint
 *   6. Call context.success() or context.failure() accordingly
 *
 * What this class does NOT do (Keycloak handles these):
 *   - Token generation
 *   - Session creation
 *   - Response formatting
 *   - Audit logging
 */
public class X509HeaderClientAuthenticator extends AbstractClientAuthenticator {

    private static final Logger logger = Logger.getLogger(X509HeaderClientAuthenticator.class);

    @Override
    public void authenticateClient(ClientAuthenticationFlowContext context) {

        // ----------------------------------------------------------------
        // STEP 1: Extract client_id from the POST form body
        // ----------------------------------------------------------------
        // The token endpoint receives: POST /token
        //   grant_type=client_credentials&client_id=myclient
        // client_id is a form parameter in the request body.

        MultivaluedMap<String, String> formParams = context
                .getHttpRequest()
                .getDecodedFormParameters();

        String clientId = formParams.getFirst(OAuth2Constants.CLIENT_ID);

        if (clientId == null || clientId.isBlank()) {
            logger.warn("X509HeaderAuth: No client_id found in request");
            sendFailure(context, "client_id is missing from the request");
            return;
        }

        logger.debugf("X509HeaderAuth: Authenticating client_id=%s", clientId);

        // ----------------------------------------------------------------
        // STEP 2: Look up the client in Keycloak
        // ----------------------------------------------------------------
        // We use the session's client store to look up by client_id string.
        // This queries the CLIENT table in Keycloak's DB.

        ClientModel client = context.getSession()
                .clients()
                .getClientByClientId(context.getRealm(), clientId);

        if (client == null) {
            logger.warnf("X509HeaderAuth: No client found for client_id=%s", clientId);
            sendFailure(context, "Unknown client: " + clientId);
            return;
        }

        // ----------------------------------------------------------------
        // STEP 3: Read the cert PEM from the x-mtls-cert header
        // ----------------------------------------------------------------
        // Imperva terminates TLS and forwards the client cert as this header.
        // The value may be URL-encoded — CertificateUtils handles that.

        String headerCertPem = context.getHttpRequest()
                .getHttpHeaders()
                .getHeaderString(X509HeaderConstants.CERT_HEADER_NAME);

        if (headerCertPem == null || headerCertPem.isBlank()) {
            logger.warnf("X509HeaderAuth: Header '%s' is missing or empty for client_id=%s",
                    X509HeaderConstants.CERT_HEADER_NAME, clientId);
            sendFailure(context, "Missing certificate header: " + X509HeaderConstants.CERT_HEADER_NAME);
            return;
        }

        // ----------------------------------------------------------------
        // STEP 4: Read the stored cert PEM from client attributes
        // ----------------------------------------------------------------
        // Stored in CLIENT_ATTRIBUTES table:
        //   NAME  = "x509.leaf.cert.pem"
        //   VALUE = "-----BEGIN CERTIFICATE-----\n..."
        //
        // This was set when the client was registered via Admin UI or REST API.

        String storedCertPem = client.getAttribute(X509HeaderConstants.CLIENT_ATTR_CERT_PEM);

        if (storedCertPem == null || storedCertPem.isBlank()) {
            logger.warnf("X509HeaderAuth: No stored cert found for client_id=%s. " +
                    "Make sure client attribute '%s' is set.",
                    clientId, X509HeaderConstants.CLIENT_ATTR_CERT_PEM);
            sendFailure(context, "No certificate registered for this client");
            return;
        }

        // ----------------------------------------------------------------
        // STEP 5: Compare fingerprints
        // ----------------------------------------------------------------
        // Both PEMs are parsed to X509Certificate → DER bytes → SHA-256 hex.
        // This is format-independent: URL-encoding, whitespace, line endings
        // don't matter — the underlying certificate bytes are always the same.

        try {
            String headerFingerprint = CertificateUtils.computeFingerprint(headerCertPem);
            String storedFingerprint = CertificateUtils.computeFingerprint(storedCertPem);

            logger.debugf("X509HeaderAuth: client_id=%s | header fingerprint=%s | stored fingerprint=%s",
                    clientId, headerFingerprint, storedFingerprint);

            if (headerFingerprint.equals(storedFingerprint)) {
                // --------------------------------------------------------
                // SUCCESS
                // --------------------------------------------------------
                // IMPORTANT: You MUST call setClient() before success().
                // Keycloak uses context.getClient() internally after this —
                // if it's null, Keycloak will NPE internally.
                logger.infof("X509HeaderAuth: Certificate match for client_id=%s — authentication successful", clientId);
                context.setClient(client);
                context.success();

            } else {
                // --------------------------------------------------------
                // FAILURE — cert mismatch
                // --------------------------------------------------------
                // Log at WARN with fingerprints so you can diagnose issues
                // without logging the full PEM (which would be a security risk).
                logger.warnf("X509HeaderAuth: Certificate fingerprint mismatch for client_id=%s. " +
                        "header=%s stored=%s",
                        clientId, headerFingerprint, storedFingerprint);
                sendFailure(context, "Certificate does not match registered certificate for this client");
            }

        } catch (Exception e) {
            // ----------------------------------------------------------------
            // FAILURE — cert could not be parsed
            // ----------------------------------------------------------------
            // This happens if:
            //   - The header value is garbage / not a valid PEM
            //   - The stored attribute value is corrupted
            //   - URL decoding fails
            logger.errorf(e, "X509HeaderAuth: Failed to parse certificate for client_id=%s", clientId);
            sendFailure(context, "Invalid certificate format");
        }
    }

    /**
     * Builds and sends a proper OAuth2 error response with HTTP 401.
     *
     * Using a proper JSON response body instead of null so that
     * clients get a meaningful error message, matching OAuth2 spec (RFC 6749).
     */
    private void sendFailure(ClientAuthenticationFlowContext context, String description) {
        String errorBody = String.format(
                "{\"error\":\"invalid_client\",\"error_description\":\"%s\"}",
                description
        );

        Response response = Response
                .status(Response.Status.UNAUTHORIZED)
                .entity(errorBody)
                .type(MediaType.APPLICATION_JSON)
                .build();

        context.failure(AuthenticationFlowError.INVALID_CLIENT_CREDENTIALS, response);
    }

    /**
     * Whether this authenticator requires additional configuration.
     * We don't have per-realm configuration — everything is hardcoded in Constants.
     */
    @Override
    public boolean isConfigurable() {
        return false;
    }

    /**
     * Configuration properties for this authenticator.
     * Empty because isConfigurable() returns false.
     */
    @Override
    public List<ProviderConfigProperty> getConfigProperties() {
        return Collections.emptyList();
    }

    /**
     * Configuration properties specific to client-level config.
     * Empty — cert is stored as a plain client attribute.
     */
    @Override
    public List<ProviderConfigProperty> getConfigPropertiesPerClient() {
        return Collections.emptyList();
    }

    /**
     * Returns protocol-specific authenticator methods.
     * Empty map — client authenticators are protocol-agnostic.
     */
    @Override
    public Map<String, Object> getProtocolAuthenticatorMethods(String protocol) {
        return Collections.emptyMap();
    }

    /**
     * Returns the adapter configuration for a specific client.
     * Not needed — we store cert as a plain attribute.
     */
    @Override
    public Object getAdapterConfiguration(ClientModel client) {
        return null;
    }

}

package com.yourorg.keycloak;

import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.MultivaluedMap;
import jakarta.ws.rs.core.Response;
